sealed class AiFailure: kotlin.Exception() {
    
    /**
     * Es läuft schon eine Anfrage dieses Assistenten.
     */
    class Busy(
        ) : AiFailure() {
        override val message
            get() = ""
    }
    
    /**
     * Mit `cancel` (oder durch Abbruch einer Rückfrage) beendet.
     */
    class Aborted(
        ) : AiFailure() {
        override val message
            get() = ""
    }
    
    class Timeout(
        
        val `reason`: kotlin.String
        ) : AiFailure() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Network(
        
        val `reason`: kotlin.String
        ) : AiFailure() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    class Http(
        
        val `status`: kotlin.UShort, 
        
        val `reason`: kotlin.String, 
        
        val `retryAfterMs`: kotlin.ULong
        ) : AiFailure() {
        override val message
            get() = "status=${ `status` }, reason=${ `reason` }, retryAfterMs=${ `retryAfterMs` }"
    }
    
    /**
     * Fehlende Einrichtung, unbrauchbare Antwort, Speicherfehler.
     */
    class Other(
        
        val `reason`: kotlin.String
        ) : AiFailure() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<AiFailure> {
        override fun lift(error_buf: RustBuffer.ByValue): AiFailure = FfiConverterTypeAiFailure.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeAiFailure : FfiConverterRustBuffer<AiFailure> {
    override fun read(buf: ByteBuffer): AiFailure {
        

        return when(buf.getInt()) {
            1 -> AiFailure.Busy()
            2 -> AiFailure.Aborted()
            3 -> AiFailure.Timeout(
                FfiConverterString.read(buf),
                )
            4 -> AiFailure.Network(
                FfiConverterString.read(buf),
                )
            5 -> AiFailure.Http(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                FfiConverterULong.read(buf),
                )
            6 -> AiFailure.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AiFailure): ULong {
        return when(value) {
            is AiFailure.Busy -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AiFailure.Aborted -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is AiFailure.Timeout -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is AiFailure.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is AiFailure.Http -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`status`)
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterULong.allocationSize(value.`retryAfterMs`)
            )
            is AiFailure.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: AiFailure, buf: ByteBuffer) {
        when(value) {
            is AiFailure.Busy -> {
                buf.putInt(1)
                Unit
            }
            is AiFailure.Aborted -> {
                buf.putInt(2)
                Unit
            }
            is AiFailure.Timeout -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is AiFailure.Network -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is AiFailure.Http -> {
                buf.putInt(5)
                FfiConverterUShort.write(value.`status`, buf)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterULong.write(value.`retryAfterMs`, buf)
                Unit
            }
            is AiFailure.Other -> {
                buf.putInt(6)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




