    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<DriveFailure> {
        override fun lift(error_buf: RustBuffer.ByValue): DriveFailure = FfiConverterTypeDriveFailure.lift(error_buf)
    }

    
}

