 */
public object FfiConverterTypeSyncFailure : FfiConverterRustBuffer<SyncFailure> {
    override fun read(buf: ByteBuffer): SyncFailure {
        

        return when(buf.getInt()) {
            1 -> SyncFailure.InvalidKey(
                FfiConverterString.read(buf),
                )
            2 -> SyncFailure.Stopped()
            3 -> SyncFailure.Failed(
                FfiConverterString.read(buf),
                FfiConverterOptionalUShort.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterBoolean.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SyncFailure): ULong {
        return when(value) {
            is SyncFailure.InvalidKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is SyncFailure.Stopped -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is SyncFailure.Failed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
                + FfiConverterOptionalUShort.allocationSize(value.`status`)
                + FfiConverterBoolean.allocationSize(value.`retryable`)
                + FfiConverterBoolean.allocationSize(value.`quota`)
            )
        }
    }

    override fun write(value: SyncFailure, buf: ByteBuffer) {
        when(value) {
            is SyncFailure.InvalidKey -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is SyncFailure.Stopped -> {
                buf.putInt(2)
                Unit
            }
            is SyncFailure.Failed -> {
                buf.putInt(3)
                FfiConverterString.write(value.`reason`, buf)
                FfiConverterOptionalUShort.write(value.`status`, buf)
                FfiConverterBoolean.write(value.`retryable`, buf)
                FfiConverterBoolean.write(value.`quota`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




